// LOCATION PING HANDLER v0.4.0 (workflow v4)
// Input shape: $json is the row from 'Resolve Driver' (one row, possibly NULL).
// Original webhook body is accessed via $('Location Ping Webhook1').

var resolved = $json || {};
var pingInput = $('Location Ping Webhook1').item.json;
var body = pingInput.body || pingInput;
var nowTs = Math.floor(Date.now() / 1000);

if (!resolved.driver_id || resolved.auth_method === 'unauthorized' || resolved.auth_method == null) {
  return [{ json: { status: 401, body: { ok: false, error: 'unauthorized' } } }];
}

var lat = parseFloat(body.lat);
var lng = parseFloat(body.lng);
if (isNaN(lat) || isNaN(lng)) {
  return [{ json: { status: 400, body: { ok: false, error: 'bad coordinates' } } }];
}
if (lat < -90 || lat > 90 || lng < -180 || lng > 180) {
  return [{ json: { status: 400, body: { ok: false, error: 'coordinates out of range' } } }];
}

var source = (body.source || 'unknown').toString().toLowerCase();
if (['iphone', 'watch', 'manual', 'shortcut'].indexOf(source) === -1) source = 'unknown';

return [{ json: {
  status: 200,
  body: {
    ok: true,
    received_at: nowTs,
    location: { lat: lat, lng: lng, source: source },
    driver: {
      id: resolved.driver_id,
      handle: resolved.driver_handle,
      auth_method: resolved.auth_method
    }
  },
  resolved_driver_id: resolved.driver_id
} }];

// v4: also pulls optional driver_handle for per-driver ETA dispatch.
var SHARED_SECRET = $env.CONCIERGE_DISPATCH_SHARED_SECRET;
var body = $json.body || $json;
var auth = body.auth;
var address = body.address;
var driverHandle = body.driver_handle || body.driver || null;

if (!SHARED_SECRET || auth !== SHARED_SECRET) {
  return [{ json: { ok: false, short_circuit: true, error: 'unauthorized', _http_status: 401 } }];
}
if (!address || !address.toString().trim()) {
  return [{ json: { ok: false, short_circuit: true, error: 'no address provided', _http_status: 400 } }];
}
return [{ json: {
  address: address.toString().trim(),
  driver_handle: driverHandle ? String(driverHandle).trim() : null
} }];

// ETA REQUEST BUILDER v0.5.0 (workflow v4)
// $json is the (always-one) row from Read Latest Ping (DB).
// Original normalize output is at $('Normalize Webhook Input').

var GOOGLE_API_KEY = $env.GOOGLE_MAPS_API_KEY;
var normalized = $('Normalize Webhook Input').item.json;

if (normalized.short_circuit === true) {
  return [{ json: normalized }];
}

var address = (normalized.address || '').toString().trim();
var nowTs = Math.floor(Date.now() / 1000);

if (!address) {
  return [{ json: { ok: false, error: 'no address provided', short_circuit: true } }];
}
if (!GOOGLE_API_KEY) {
  return [{ json: { ok: false, error: 'google api key not configured', short_circuit: true } }];
}

var pingRow = $json;
if (!pingRow || pingRow.lat == null || pingRow.lng == null) {
  var reason = normalized.driver_handle
    ? ('no ping yet for driver "' + normalized.driver_handle + '" -- have them tap concierge ping on phone')
    : 'no location ping yet -- tap concierge ping on phone';
  return [{ json: { ok: false, error: reason, short_circuit: true } }];
}

var loc = {
  lat: Number(pingRow.lat),
  lng: Number(pingRow.lng),
  source: pingRow.source || 'unknown',
  driver_id: pingRow.driver_id,
  driver_handle: pingRow.driver_handle
};
var pingTs = Math.floor(new Date(pingRow.ts).getTime() / 1000);
var locationAgeSec = nowTs - pingTs;
var locationStale = locationAgeSec > 900;

var destAddress = address;
if (!/montreal|laval|brossard|quebec|qc|montréal/i.test(destAddress)) {
  destAddress = destAddress + ', Montreal, QC, Canada';
}

var url = 'https://maps.googleapis.com/maps/api/distancematrix/json' +
  '?origins=' + loc.lat + ',' + loc.lng +
  '&destinations=' + encodeURIComponent(destAddress) +
  '&mode=driving' +
  '&departure_time=now' +
  '&units=metric' +
  '&region=ca' +
  '&key=' + GOOGLE_API_KEY;

return [{ json: {
  ok: true,
  short_circuit: false,
  url: url,
  address_input: address,
  address_resolved: destAddress,
  origin: loc,
  location_age_seconds: locationAgeSec,
  location_stale: locationStale,
  requested_at: nowTs
} }];

// ETA RESPONSE PARSER v0.5.0 — unchanged from v3 (response shape stable).
var BUFFER_MIN = 5;

var response = $json;
var buildCtx = $('Build ETA Request1').item.json;
if (response.status !== 'OK') {
  return [{ json: { ok: false, error: 'google_api_error', google_status: response.status, google_message: response.error_message || null } }];
}
if (!response.rows || !response.rows[0] || !response.rows[0].elements || !response.rows[0].elements[0]) {
  return [{ json: { ok: false, error: 'malformed_google_response', raw: response } }];
}
var element = response.rows[0].elements[0];
if (element.status !== 'OK') {
  return [{ json: { ok: false, error: 'no_route_found', element_status: element.status, address_tried: buildCtx.address_resolved } }];
}
var etaSeconds = (element.duration_in_traffic && element.duration_in_traffic.value) ? element.duration_in_traffic.value : element.duration.value;
var etaMinutes = Math.round(etaSeconds / 60);
var distanceMeters = element.distance.value;
var distanceKm = Math.round((distanceMeters / 1000) * 10) / 10;
var nowTs = Math.floor(Date.now() / 1000);
var arrivalTs = nowTs + etaSeconds;
var arrivalDate = new Date(arrivalTs * 1000);

var clientEtaMinutes = etaMinutes + BUFFER_MIN;
var clientArrivalDate = new Date((arrivalTs + BUFFER_MIN * 60) * 1000);

function formatArrivalLabel(d) {
  var fmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Toronto', hour: 'numeric', minute: '2-digit', hour12: true });
  return fmt.format(d).toLowerCase().replace(/\s/g, '');
}
var arrivalLabel = formatArrivalLabel(arrivalDate);
var arrivalIso = arrivalDate.toISOString();
var clientArrivalLabel = formatArrivalLabel(clientArrivalDate);
var clientArrivalIso = clientArrivalDate.toISOString();

var origin = buildCtx.origin;
var mapsUrl = 'https://www.google.com/maps/dir/?api=1' +
  '&origin=' + origin.lat + ',' + origin.lng +
  '&destination=' + encodeURIComponent(buildCtx.address_resolved) +
  '&travelmode=driving';

return [{ json: {
  ok: true,
  eta_seconds: etaSeconds,
  eta_minutes: etaMinutes,
  distance_m: distanceMeters,
  distance_km: distanceKm,
  distance_text: element.distance.text,
  duration_text: (element.duration_in_traffic && element.duration_in_traffic.text) || element.duration.text,
  arrival_iso: arrivalIso,
  arrival_label: arrivalLabel,
  client_eta_minutes: clientEtaMinutes,
  client_arrival_iso: clientArrivalIso,
  client_arrival_label: clientArrivalLabel,
  buffer_minutes: BUFFER_MIN,
  maps_url: mapsUrl,
  origin: origin,
  address_input: buildCtx.address_input,
  address_resolved: buildCtx.address_resolved,
  location_age_seconds: buildCtx.location_age_seconds,
  location_stale: buildCtx.location_stale,
  calculated_at: nowTs
} }];

var etaPayload = $('Parse ETA Response1').item.json;
var snapRow = $json;
var snapshotId = (snapRow && typeof snapRow.id === 'number') ? snapRow.id : null;
return [{ json: Object.assign({}, etaPayload, { snapshot_id: snapshotId }) }];

// /area-snapshot — Client Area Snapshot generator (§6). v4: optional driver_handle.
// Keep jitter logic in sync with scripts/jitter.ts.

var SHARED_SECRET = $env.CONCIERGE_DISPATCH_SHARED_SECRET;
var webhookData = $('Area Snapshot Webhook').item.json;
var pingRow = $json;
var body = webhookData.body || webhookData;

console.log(
  'auth len/type',
  typeof body?.auth,
  (body?.auth || '').length
);
console.log(
  'secret set?',
  !!SHARED_SECRET,
  typeof SHARED_SECRET,
  (SHARED_SECRET || '').length
);

if (!SHARED_SECRET || !body || body.auth !== SHARED_SECRET) {
  return [{ json: { status: 401, body: { ok: false, error: 'unauthorized' } } }];
}

var radiusM = parseInt(body.radius_m, 10);
if (![1000, 2000, 5000].includes(radiusM)) {
  return [{ json: { status: 400, body: { ok: false, error: 'radius_m must be 1000, 2000, or 5000' } } }];
}
var label = radiusM === 1000 ? '1km' : radiusM === 2000 ? '2km' : '5km';

if (!pingRow || pingRow.lat == null) {
  var reason = body.driver_handle
    ? ('no_ping_for_driver:' + body.driver_handle)
    : 'no_ping_yet';
  return [{ json: { status: 409, body: { ok: false, error: reason } } }];
}
var age = Number(pingRow.age_seconds);
if (!isFinite(age) || age > 900) {
  return [{ json: { status: 409, body: { ok: false, error: 'location_stale', age_seconds: age } } }];
}

// --- jitter (inlined from scripts/jitter.ts) ---
function seededRandom(seed) {
  var x = (seed + 0x6D2B79F5) >>> 0;
  var r = (x ^ (x >>> 15)) >>> 0;
  r = Math.imul(r, 1 | r) >>> 0;
  r = (r ^ (r + Math.imul(r ^ (r >>> 7), 61 | r))) >>> 0;
  return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
}
function hashTwo(a, b) {
  return (Math.imul(a | 0, 2654435761) + Math.imul(b | 0, 2246822519)) >>> 0;
}
function jitterFraction(driverId, hourBucket, axis) {
  var seed = hashTwo(driverId, hourBucket * 2 + axis);
  return seededRandom(seed) * 0.5 - 0.25;
}

var grid = radiusM === 1000 ? 0.01 : radiusM === 2000 ? 0.02 : 0.05;
var lat = Number(pingRow.lat);
var lng = Number(pingRow.lng);
var driverId = Number(pingRow.driver_id);
var qLat = Math.round(lat / grid) * grid;
var qLng = Math.round(lng / grid) * grid;

var hourBucket = Math.floor(Date.now() / 3600000);
var jLatFrac = jitterFraction(driverId, hourBucket, 0);
var jLngFrac = jitterFraction(driverId, hourBucket, 1);
var latDegPerM = 1 / 111111;
var lngDegPerM = 1 / (111111 * Math.cos((qLat * Math.PI) / 180));
var centerLat = qLat + jLatFrac * radiusM * latDegPerM;
var centerLng = qLng + jLngFrac * radiusM * lngDegPerM;

var mapUrl = 'https://www.google.com/maps/?q=' + centerLat + ',' + centerLng;
var expiresInSec = 1800; // 30 min
var expiresAtIso = new Date(Date.now() + expiresInSec * 1000).toISOString();

return [{ json: {
  _insert: {
    driver_id: driverId,
    center_lat: centerLat,
    center_lng: centerLng,
    radius_m: radiusM,
    precision_label: label,
    expires_at: expiresAtIso,
    map_url: mapUrl,
    trip_id: body.trip_id != null ? Number(body.trip_id) : null,
    client_id: body.client_id != null ? Number(body.client_id) : null
  },
  status: 200,
  body: {
    ok: true,
    map_url: mapUrl,
    radius_label: label,
    radius_m: radiusM,
    expires_at: expiresAtIso,
    ping_age_seconds: age,
    driver_handle: pingRow.driver_handle
  }
} }];
